import glob

MILES_TO_KM = 1.06

totals = {}
for path in glob.glob("trips/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            van, miles = line.strip().split(",")
            totals[van] = totals.get(van, 0) + int(miles)
for van in sorted(totals):
    print(f"{van} {int(totals[van] * MILES_TO_KM)} km")
